ST.xhtml:p:
(*抽尘阀(hmi)  打开*)
R_Trigger7(CLK := g_bDustGasValveOpenM OR g_bDustGasValveOpen OR bDustGasValveOpen);
IF R_Trigger7.Q THEN
  g_boDustGasValve := TRUE;
  g_bDustGasValveState := TRUE;
  g_bDustGasValveOpenM := FALSE;
  g_bDustGasValveOpen := FALSE;
  bDustGasValveOpen := FALSE;
  M.ENABLE[227] := 0;
END_IF;

(*抽尘阀(hmi)  关闭*)
R_Trigger8(CLK := g_bDustGasValveCloseM OR g_bDustGasValveClose OR bDustGasValveClose);
IF R_Trigger8.Q THEN
  g_boDustGasValve := FALSE;
  g_bDustGasValveState := FALSE;
  g_bDustGasValveCloseM := FALSE;
  g_bDustGasValveClose := FALSE;
  bDustGasValveClose := FALSE;
   M.ENABLE[227] := 0;
END_IF;

IF g_bPlcResetBuffer THEN
  g_bDustGasValveCloseM := FALSE;
  g_bDustGasValveOpenM := FALSE;
END_IF;
